<?php declare(strict_types=1);use App\Core\Database\Database;use App\Modules\SubcontractPayments\Repositories\SubcontractPaymentRepository;/** @var Database $db */$db=$app->make(Database::class);$r=$db->execute("SELECT COUNT(*) n FROM permissions WHERE module='subcontract_payments'");if((int)(($r instanceof mysqli_result?$r->fetch_assoc():[])['n']??0)!==5)throw new RuntimeException('Payment permissions missing.');$r=$db->execute("SELECT COUNT(*) n FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='subcontract_payments' AND column_name IN('created_by','posted_at','posted_by','cancelled_at','cancelled_by','approved_progress_percentage_snapshot','approved_earned_value_snapshot','previous_payments_snapshot','available_payment_snapshot')");if((int)(($r instanceof mysqli_result?$r->fetch_assoc():[])['n']??0)!==9)throw new RuntimeException('Payment audit/snapshots missing.');/** @var SubcontractPaymentRepository $repo */$repo=$app->make(SubcontractPaymentRepository::class);$a=$repo->availability('20000.00','15000.00');if((float)$a['available']!==5000.0||(int)$a['inconsistent']!==0)throw new RuntimeException('Availability calculation failed.');$a=$repo->availability('100.00','101.00');if((float)$a['available']!==0.0||(int)$a['inconsistent']!==1)throw new RuntimeException('Inconsistency handling failed.');if(!$repo->amountExceeds('5000.01','5000.00')||$repo->amountExceeds('5000.00','5000.00'))throw new RuntimeException('Payment ceiling comparison failed.');
